<section class="lesson-reader"><header><p class="eyebrow"><?= htmlspecialchars($lesson['module_title']) ?></p><h1><?= htmlspecialchars($lesson['title']) ?></h1><p><?= htmlspecialchars($lesson['course_title']) ?> · <?= (int)$lesson['duration'] ?> minutes</p></header><main class="panel lesson-material"><?php if($lesson['type']==='video'): ?><?php if(str_contains($lesson['content']??'','youtube.com')||str_contains($lesson['content']??'','youtu.be')): ?><iframe src="<?= htmlspecialchars($lesson['content']) ?>" allowfullscreen></iframe><?php else: ?><video controls controlsList="nodownload"><source src="<?= htmlspecialchars($lesson['content']) ?>"></video><?php endif ?><?php elseif($lesson['type']==='text'): ?><article class="rich-text"><?= nl2br(htmlspecialchars($lesson['content'])) ?></article><?php else: ?><div class="download-material"><span>↓</span><h2>Ressource pédagogique</h2><a class="btn primary" href="<?= htmlspecialchars($lesson['content']) ?>" target="_blank">Télécharger le document</a></div><?php endif ?></main><footer><a class="btn secondary" href="/academie/formation?course=<?= $lesson['course_id'] ?>">← Retour au programme</a><form method="post" action="/academie/lecon/terminer"><input type="hidden" name="lesson_id" value="<?= $lesson['id'] ?>"><input type="hidden" name="course_id" value="<?= $lesson['course_id'] ?>"><button class="btn primary">✓ Marquer comme terminée</button></form></footer></section><style>.lesson-reader{max-width:980px;margin:auto}.lesson-reader header{text-align:center;margin-bottom:25px}.lesson-material{min-height:420px;display:grid;place-items:center;overflow:hidden}.lesson-material video,.lesson-material iframe{width:100%;aspect-ratio:16/9;border:0;background:#111}.rich-text{padding:45px;line-height:1.9;align-self:start}.download-material{text-align:center}.download-material>span{font-size:50px;color:var(--primary)}.lesson-reader>footer{display:flex;justify-content:space-between;margin-top:18px}</style>
